#![cfg(feature = "go")]

use code_gen::go::*;
use code_gen::*;

/// The comment at the top of a generated file.
const HEADER: &str = "// Code generated by the ProtoPacket compiler. DO NOT EDIT.";

/// Renders the `statement` with the tab indent of `gofmt`.
fn to_go<S: Statement>(statement: &S) -> String {
    let mut b: CodeBuffer = CodeBuffer::new("\t", "\n", CodeBuffer::DEFAULT_CAPACITY);
    statement.write(&mut b, 0);
    b.into()
}

#[test]
fn struct_file() {
    let pointer: GoType = GoType::from("Point").to_pointer();
    let bytes: GoType = GoType::from("byte").to_slice();

    let imports: ImportBlock = ImportBlock::default()
        .with_import("encoding/binary")
        .with_import("errors");
    let size: ConstInit = ConstInit::from((("PointSize", "int"), Literal::from("8")))
        .with_comment(" PointSize is the length of an encoded Point, in bytes.");
    let error: VarInit = VarInit::from((
        ("errPointLength", "error"),
        Literal::from("errors.New(\"invalid point length\")"),
    ));
    let point: Struct = Struct::from("Point")
        .with_comment(" Point is a point.")
        .with_field(("x", "uint32"))
        .with_field(("y", "uint32"));
    let constructor: Function = Function::from(
        Signature::from("NewPoint")
            .with_param(("x", "uint32"))
            .with_param(("y", "uint32"))
            .with_result(pointer.clone()),
    )
    .with_comment(" NewPoint creates a new Point.")
    .with_literal("return &Point{x: x, y: y}");
    let encode: Function = Function::from(
        Signature::from("Encode")
            .with_param(("out", bytes.clone()))
            .with_result(bytes.clone()),
    )
    .with_comment(" Encode appends the encoding of the point to the out bytes.")
    .with_receiver(("p", pointer.clone()))
    .with_literal("out = binary.LittleEndian.AppendUint32(out, p.x)")
    .with_literal("out = binary.LittleEndian.AppendUint32(out, p.y)")
    .with_literal("return out");
    let decode: Function = Function::from(
        Signature::from("DecodePoint")
            .with_param(("bytes", bytes))
            .with_result(pointer.clone())
            .with_result("error"),
    )
    .with_comment(" DecodePoint decodes a point from the bytes.")
    .with_statement(
        IfStatement::from("len(bytes) != PointSize")
            .with_success_statements(Block::default().with_literal("return nil, errPointLength")),
    )
    .with_literal("x := binary.LittleEndian.Uint32(bytes[0:4])")
    .with_literal("y := binary.LittleEndian.Uint32(bytes[4:8])")
    .with_literal("return NewPoint(x, y), nil");

    let mut file: Block = Block::default()
        .with_literal(HEADER)
        .with_empty_line()
        .with_literal("package examples")
        .with_empty_line()
        .with_statement(imports)
        .with_empty_line()
        .with_statement(size)
        .with_empty_line()
        .with_statement(error)
        .with_empty_line()
        .with_statement(point)
        .with_empty_line()
        .with_statement(constructor);
    for (field, name) in [("x", "X"), ("y", "Y")] {
        file.add_empty_line();
        file.add_statement(
            Function::from(Signature::from(name).with_result("uint32"))
                .with_comment(format!(" {name} gets the field: {field}."))
                .with_receiver(("p", pointer.clone()))
                .with_literal(format!("return p.{field}")),
        );
        file.add_empty_line();
        file.add_statement(
            Function::from(Signature::from(format!("Set{name}")).with_param((field, "uint32")))
                .with_comment(format!(" Set{name} sets the field: {field}."))
                .with_receiver(("p", pointer.clone()))
                .with_literal(format!("p.{field} = {field}")),
        );
    }
    file.add_empty_line();
    file.add_statement(encode);
    file.add_empty_line();
    file.add_statement(decode);

    assert_eq!(
        to_go(&file),
        "\
// Code generated by the ProtoPacket compiler. DO NOT EDIT.

package examples

import (
\t\"encoding/binary\"
\t\"errors\"
)

// PointSize is the length of an encoded Point, in bytes.
const PointSize int = 8

var errPointLength error = errors.New(\"invalid point length\")

// Point is a point.
type Point struct {
\tx uint32
\ty uint32
}

// NewPoint creates a new Point.
func NewPoint(x uint32, y uint32) *Point {
\treturn &Point{x: x, y: y}
}

// X gets the field: x.
func (p *Point) X() uint32 {
\treturn p.x
}

// SetX sets the field: x.
func (p *Point) SetX(x uint32) {
\tp.x = x
}

// Y gets the field: y.
func (p *Point) Y() uint32 {
\treturn p.y
}

// SetY sets the field: y.
func (p *Point) SetY(y uint32) {
\tp.y = y
}

// Encode appends the encoding of the point to the out bytes.
func (p *Point) Encode(out []byte) []byte {
\tout = binary.LittleEndian.AppendUint32(out, p.x)
\tout = binary.LittleEndian.AppendUint32(out, p.y)
\treturn out
}

// DecodePoint decodes a point from the bytes.
func DecodePoint(bytes []byte) (*Point, error) {
\tif len(bytes) != PointSize {
\t\treturn nil, errPointLength
\t}
\tx := binary.LittleEndian.Uint32(bytes[0:4])
\ty := binary.LittleEndian.Uint32(bytes[4:8])
\treturn NewPoint(x, y), nil
}
"
    );
}

#[test]
fn message() {
    let label: Struct = Struct::from("Label")
        .with_comment(" Label is a label.")
        .with_field(
            StructField::from(("Text", GoType::from("string").to_pointer()))
                .with_comment(" Text is the field: text.")
                .with_tag("json:\"text,omitempty\""),
        )
        .with_field(
            StructField::from(("Tags", GoType::from("string").to_slice()))
                .with_comment(" Tags is the field: tags.")
                .with_tag("json:\"tags,omitempty\""),
        )
        .with_field(
            StructField::from(("Key", GoType::from("byte").to_array(16).to_pointer()))
                .with_comment(" Key is the field: key.")
                .with_tag("json:\"key,omitempty\""),
        );
    let fields: SwitchStatement = SwitchStatement::from("tagNumber")
        .with_switch_case(
            SwitchCase::from("1")
                .with_literal("text := string(value)")
                .with_literal("label.Text = &text"),
        )
        .with_switch_case(
            SwitchCase::from("2").with_literal("label.Tags = append(label.Tags, string(value))"),
        )
        .with_switch_case(
            SwitchCase::from("3")
                .with_literal("key := [16]byte(value)")
                .with_literal("label.Key = &key"),
        );
    let decode: Function = Function::from(
        Signature::from("DecodeLabel")
            .with_param(("bytes", GoType::from("byte").to_slice()))
            .with_result(GoType::from("Label").to_pointer())
            .with_result("error"),
    )
    .with_comment(" DecodeLabel decodes a label from the bytes.")
    .with_literal("label := &Label{}")
    .with_statement(
        ForLoop::from("len(bytes) > 0")
            .with_literal("tagNumber, value, rest, err := pp.ReadField(bytes)")
            .with_statement(
                IfStatement::from("err != nil")
                    .with_success_statements(Block::default().with_literal("return nil, err")),
            )
            .with_statement(fields)
            .with_literal("bytes = rest"),
    )
    .with_literal("return label, nil");

    let code: Block = Block::default()
        .with_statement(label)
        .with_empty_line()
        .with_statement(decode);

    assert_eq!(
        to_go(&code),
        "\
// Label is a label.
type Label struct {
\t// Text is the field: text.
\tText *string `json:\"text,omitempty\"`

\t// Tags is the field: tags.
\tTags []string `json:\"tags,omitempty\"`

\t// Key is the field: key.
\tKey *[16]byte `json:\"key,omitempty\"`
}

// DecodeLabel decodes a label from the bytes.
func DecodeLabel(bytes []byte) (*Label, error) {
\tlabel := &Label{}
\tfor len(bytes) > 0 {
\t\ttagNumber, value, rest, err := pp.ReadField(bytes)
\t\tif err != nil {
\t\t\treturn nil, err
\t\t}
\t\tswitch tagNumber {
\t\tcase 1:
\t\t\ttext := string(value)
\t\t\tlabel.Text = &text
\t\tcase 2:
\t\t\tlabel.Tags = append(label.Tags, string(value))
\t\tcase 3:
\t\t\tkey := [16]byte(value)
\t\t\tlabel.Key = &key
\t\t}
\t\tbytes = rest
\t}
\treturn label, nil
}
"
    );
}

#[test]
fn enumeration() {
    let color: TypeDef = TypeDef::from(("Color", "uint16")).with_comment(" Color is a color.");
    let cases: ConstBlock = ConstBlock::default()
        .with_comment(" The cases of Color. Any other tag number is an unrecognized case.")
        .with_constant(
            ConstInit::from((("ColorRed", "Color"), Literal::from("1")))
                .with_comment(" ColorRed is red."),
        )
        .with_constant(
            ConstInit::from((("ColorGreen", "Color"), Literal::from("2")))
                .with_comment(" ColorGreen is green."),
        );
    let is_recognized: Function =
        Function::from(Signature::from("IsRecognized").with_result("bool"))
            .with_comment(" IsRecognized checks if the enum knows the case.")
            .with_receiver(("c", "Color"))
            .with_statement(
                SwitchStatement::from("c")
                    .with_switch_case(
                        SwitchCase::from("ColorRed, ColorGreen").with_literal("return true"),
                    )
                    .with_switch_case(SwitchCase::default().with_literal("return false")),
            );
    let string: Function = Function::from(Signature::from("String").with_result("string"))
        .with_comment(" String gets the name of the case.")
        .with_receiver(("c", "Color"))
        .with_statement(
            SwitchStatement::from("c")
                .with_switch_case(SwitchCase::from("ColorRed").with_literal("return \"Red\""))
                .with_switch_case(SwitchCase::from("ColorGreen").with_literal("return \"Green\""))
                .with_switch_case(
                    SwitchCase::default()
                        .with_literal("return fmt.Sprintf(\"Color(%d)\", uint16(c))"),
                ),
        );

    let code: Block = Block::default()
        .with_statement(color)
        .with_empty_line()
        .with_statement(cases)
        .with_empty_line()
        .with_statement(is_recognized)
        .with_empty_line()
        .with_statement(string);

    assert_eq!(
        to_go(&code),
        "\
// Color is a color.
type Color uint16

// The cases of Color. Any other tag number is an unrecognized case.
const (
\t// ColorRed is red.
\tColorRed Color = 1

\t// ColorGreen is green.
\tColorGreen Color = 2
)

// IsRecognized checks if the enum knows the case.
func (c Color) IsRecognized() bool {
\tswitch c {
\tcase ColorRed, ColorGreen:
\t\treturn true
\tdefault:
\t\treturn false
\t}
}

// String gets the name of the case.
func (c Color) String() string {
\tswitch c {
\tcase ColorRed:
\t\treturn \"Red\"
\tcase ColorGreen:
\t\treturn \"Green\"
\tdefault:
\t\treturn fmt.Sprintf(\"Color(%d)\", uint16(c))
\t}
}
"
    );
}

/// Builds the methods that make the `case` a `Shape` with the `tag_number`.
fn shape_methods(case: &str, tag_number: &str) -> Block {
    Block::default()
        .with_statement(
            Function::from(Signature::from("TagNumber").with_result("uint16"))
                .with_comment(" TagNumber gets the tag number of the case.")
                .with_receiver(("c", case))
                .with_literal(format!("return {tag_number}")),
        )
        .with_empty_line()
        .with_statement(Function::from("isShape").with_receiver(("c", case)))
}

#[test]
fn variant() {
    let shape: Interface = Interface::from("Shape")
        .with_comment(" Shape is a shape. Its cases are the types with the isShape method.")
        .with_signature_dec(
            SignatureDec::from(Signature::from("TagNumber").with_result("uint16"))
                .with_comment(" TagNumber gets the tag number of the case."),
        )
        .with_signature_dec("isShape");
    let circle: Struct = Struct::from("ShapeCircle")
        .with_comment(" ShapeCircle is the case: Circle.")
        .with_field(("Value", "Circle"));
    let unrecognized: Struct = Struct::from("ShapeUnrecognized")
        .with_comment(" ShapeUnrecognized is a case the variant doesn't know.")
        .with_field(("tagNumber", "uint16"))
        .with_field(("bytes", GoType::from("byte").to_slice()));
    let encode: Function = Function::from(
        Signature::from("EncodeShape")
            .with_param(("shape", "Shape"))
            .with_param(("out", GoType::from("byte").to_slice()))
            .with_result(GoType::from("byte").to_slice()),
    )
    .with_comment(" EncodeShape appends the encoding of the shape to the out bytes.")
    .with_literal("out = binary.LittleEndian.AppendUint16(out, shape.TagNumber())")
    .with_statement(
        SwitchStatement::from("c := shape.(type)")
            .with_switch_case(
                SwitchCase::from("ShapeCircle").with_literal("return c.Value.Encode(out)"),
            )
            .with_switch_case(
                SwitchCase::from("ShapeUnrecognized")
                    .with_literal("return append(out, c.bytes...)"),
            )
            .with_switch_case(SwitchCase::default().with_literal("panic(\"unreachable\")")),
    );

    let code: Block = Block::default()
        .with_statement(shape)
        .with_empty_line()
        .with_statement(circle)
        .with_empty_line()
        .with_statement(shape_methods("ShapeCircle", "1"))
        .with_empty_line()
        .with_statement(unrecognized)
        .with_empty_line()
        .with_statement(shape_methods("ShapeUnrecognized", "c.tagNumber"))
        .with_empty_line()
        .with_statement(encode);

    assert_eq!(
        to_go(&code),
        "\
// Shape is a shape. Its cases are the types with the isShape method.
type Shape interface {
\t// TagNumber gets the tag number of the case.
\tTagNumber() uint16

\tisShape()
}

// ShapeCircle is the case: Circle.
type ShapeCircle struct {
\tValue Circle
}

// TagNumber gets the tag number of the case.
func (c ShapeCircle) TagNumber() uint16 {
\treturn 1
}

func (c ShapeCircle) isShape() {}

// ShapeUnrecognized is a case the variant doesn't know.
type ShapeUnrecognized struct {
\ttagNumber uint16
\tbytes []byte
}

// TagNumber gets the tag number of the case.
func (c ShapeUnrecognized) TagNumber() uint16 {
\treturn c.tagNumber
}

func (c ShapeUnrecognized) isShape() {}

// EncodeShape appends the encoding of the shape to the out bytes.
func EncodeShape(shape Shape, out []byte) []byte {
\tout = binary.LittleEndian.AppendUint16(out, shape.TagNumber())
\tswitch c := shape.(type) {
\tcase ShapeCircle:
\t\treturn c.Value.Encode(out)
\tcase ShapeUnrecognized:
\t\treturn append(out, c.bytes...)
\tdefault:
\t\tpanic(\"unreachable\")
\t}
}
"
    );
}

#[test]
fn view() {
    let view: Interface = Interface::from("PointView")
        .with_comment(" PointView is the fields of any form of Point.")
        .with_signature_dec(
            SignatureDec::from(Signature::from("X").with_result("uint32"))
                .with_comment(" X gets the field: x."),
        )
        .with_signature_dec(
            SignatureDec::from(Signature::from("Y").with_result("uint32"))
                .with_comment(" Y gets the field: y."),
        );
    let view_mut: Interface = Interface::from("PointViewMut")
        .with_comment(" PointViewMut is the editable fields of any editable form of Point.")
        .with_embedded("PointView")
        .with_signature_dec(
            SignatureDec::from(Signature::from("SetX").with_param(("x", "uint32")))
                .with_comment(" SetX sets the field: x."),
        )
        .with_signature_dec(
            SignatureDec::from(Signature::from("SetY").with_param(("y", "uint32")))
                .with_comment(" SetY sets the field: y."),
        );
    let reference: Struct = Struct::from("PointRef")
        .with_comment(" PointRef is a read-only view of an encoded Point.")
        .with_field(("bytes", GoType::from("byte").to_slice()));
    let x: Function = Function::from(Signature::from("X").with_result("uint32"))
        .with_comment(" X gets the field: x.")
        .with_receiver(("r", "PointRef"))
        .with_literal("return binary.LittleEndian.Uint32(r.bytes[0:4])");
    let y: Function = Function::from(Signature::from("Y").with_result("uint32"))
        .with_comment(" Y gets the field: y.")
        .with_receiver(("r", "PointRef"))
        .with_literal("return binary.LittleEndian.Uint32(r.bytes[4:8])");
    let buf: Struct = Struct::from("PointBuf")
        .with_comment(" PointBuf is an owned encoded Point. It has the getters of PointRef.")
        .with_embedded("PointRef");

    let code: Block = Block::default()
        .with_statement(view)
        .with_empty_line()
        .with_statement(view_mut)
        .with_empty_line()
        .with_statement(reference)
        .with_empty_line()
        .with_statement(x)
        .with_empty_line()
        .with_statement(y)
        .with_empty_line()
        .with_statement(buf);

    assert_eq!(
        to_go(&code),
        "\
// PointView is the fields of any form of Point.
type PointView interface {
\t// X gets the field: x.
\tX() uint32

\t// Y gets the field: y.
\tY() uint32
}

// PointViewMut is the editable fields of any editable form of Point.
type PointViewMut interface {
\tPointView

\t// SetX sets the field: x.
\tSetX(x uint32)

\t// SetY sets the field: y.
\tSetY(y uint32)
}

// PointRef is a read-only view of an encoded Point.
type PointRef struct {
\tbytes []byte
}

// X gets the field: x.
func (r PointRef) X() uint32 {
\treturn binary.LittleEndian.Uint32(r.bytes[0:4])
}

// Y gets the field: y.
func (r PointRef) Y() uint32 {
\treturn binary.LittleEndian.Uint32(r.bytes[4:8])
}

// PointBuf is an owned encoded Point. It has the getters of PointRef.
type PointBuf struct {
\tPointRef
}
"
    );
}

#[test]
fn service_file() {
    let imports: ImportBlock = ImportBlock::default()
        .with_import("context")
        .with_import(Import::from("example.com/protopacket").with_alias("pp"))
        .with_import("net/http");
    let greet: Signature = Signature::from("Greet")
        .with_param(("ctx", "context.Context"))
        .with_param(("request", GoType::from("GreetRequest").to_pointer()))
        .with_result(GoType::from("GreetResponse").to_pointer())
        .with_result("error");
    let greeter: Interface = Interface::from("Greeter")
        .with_comment(" Greeter is a greeter.")
        .with_signature_dec(SignatureDec::from(greet).with_comment(" Greet greets the name."));
    let handler: Function = Function::from(
        Signature::from("NewGreeterHandler")
            .with_param(("service", "Greeter"))
            .with_result("http.Handler"),
    )
    .with_comment(" NewGreeterHandler creates the HTTP handler of the Greeter service.")
    .with_literal("mux := http.NewServeMux()")
    .with_literal(
        "mux.Handle(\"POST /services.calls.Greeter/greet\", pp.NewCallHandler(service.Greet))",
    )
    .with_literal("return mux");

    let file: Block = Block::default()
        .with_literal(HEADER)
        .with_empty_line()
        .with_literal("package calls")
        .with_empty_line()
        .with_statement(imports)
        .with_empty_line()
        .with_statement(greeter)
        .with_empty_line()
        .with_statement(handler);

    assert_eq!(
        to_go(&file),
        "\
// Code generated by the ProtoPacket compiler. DO NOT EDIT.

package calls

import (
\t\"context\"
\tpp \"example.com/protopacket\"
\t\"net/http\"
)

// Greeter is a greeter.
type Greeter interface {
\t// Greet greets the name.
\tGreet(ctx context.Context, request *GreetRequest) (*GreetResponse, error)
}

// NewGreeterHandler creates the HTTP handler of the Greeter service.
func NewGreeterHandler(service Greeter) http.Handler {
\tmux := http.NewServeMux()
\tmux.Handle(\"POST /services.calls.Greeter/greet\", pp.NewCallHandler(service.Greet))
\treturn mux
}
"
    );
}
